// Shared ownership genuinely needed -- no single subsystem can say "delete this"
std::shared_ptr<MarketDataCache> cache = std::make_shared<MarketDataCache>();
PricingEngine pricer(cache);
RiskEngine risk(cache);
Logger logger(cache);
// cache is destroyed only when pricer, risk, AND logger have all released it

std::vector<double> a = {1.0, 2.0, 3.0};
std::vector<double> b = std::move(a);
// std::move does nothing by itself -- it's a cast.
// vector's move constructor is what actually transfers the buffer pointer.
// a is now valid but unspecified -- typically empty.

#include <atomic>

std::atomic<long> trade_count{0};

void record_trades(int n) {
    for (int i = 0; i < n; ++i) {
        trade_count.fetch_add(1, std::memory_order_relaxed);
    }
}
// std::thread a(record_trades, 100000);
// std::thread b(record_trades, 100000);
// a.join(); b.join();
// trade_count now reliably equals 200000

namespace py = pybind11;

class Bond {
public:
    Bond(double faceValue, double couponRate, int years)
        : faceValue_(faceValue), couponRate_(couponRate), years_(years) {}
    double price(double yield) const { /* ... */ return 0.0; }
private:
    double faceValue_, couponRate_;
    int years_;
};

PYBIND11_MODULE(quantlib_cpp, m) {
    py::class_<Bond>(m, "Bond")
        .def(py::init<double, double, int>(),
             py::arg("face_value"), py::arg("coupon_rate"), py::arg("years"))
        .def("price", &Bond::price, py::arg("yield"));
}

